import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.B3IQijK_.js";const u=JSON.parse('{"title":"Set up your Trading Office","description":"Create a trading book, build the team, choose an operating mode, and review mandates and scheduled workflows.","frontmatter":{"title":"Set up your Trading Office","description":"Create a trading book, build the team, choose an operating mode, and review mandates and scheduled workflows.","outline":2,"head":[["link",{"rel":"canonical","href":"https://tradecli.in/wiki/trading-office/setup"}]]},"headers":[],"relativePath":"trading-office/setup.md","filePath":"trading-office/setup.md"}'),n={name:"trading-office/setup.md"};function r(s,e,d,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="set-up-your-trading-office" tabindex="-1">Set up your Trading Office <a class="header-anchor" href="#set-up-your-trading-office" aria-label="Permalink to &quot;Set up your Trading Office&quot;">​</a></h1><p>A ready office has a trading book, at least one active employee, and a clear decision about whether scheduled employee workflows may run. Start in Guided mode; choose Autonomous · Paper trading only after the mandates and workflows match your intent.</p><h2 id="_1-enter-trading-office" tabindex="-1">1. Enter Trading Office <a class="header-anchor" href="#_1-enter-trading-office" aria-label="Permalink to &quot;1. Enter Trading Office&quot;">​</a></h2><p>Launch <code>tradecli</code> and choose <strong>Hedge Fund</strong>, the current interface name for Trading Office. The lead surface is currently labeled the <strong>CEO pane</strong>. It opens the book picker and coordinates setup, employees, and Office controls.</p><p>Use <code>/persona</code> when you need to leave another workflow and choose Hedge Fund. Once the lead pane is open, continue with the book picker below.</p><h2 id="_2-create-or-select-a-trading-book" tabindex="-1">2. Create or select a trading book <a class="header-anchor" href="#_2-create-or-select-a-trading-book" aria-label="Permalink to &quot;2. Create or select a trading book&quot;">​</a></h2><p>Open the book picker:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/hedgefund:books</span></span></code></pre></div><p>A trading book is the boundary for paper cash, positions, transactions, NAV, P&amp;L, employees, research, and workflows. The current interface labels it a <strong>fund book</strong>. Each book also carries its market context: India or the US.</p><p>You can create more than one book, but one is active in a Trading Office session. Check the book name and opening cash before starting work; research and paper actions should always land in the intended book.</p><h2 id="_3-build-your-ai-team" tabindex="-1">3. Build your AI team <a class="header-anchor" href="#_3-build-your-ai-team" aria-label="Permalink to &quot;3. Build your AI team&quot;">​</a></h2><p>Before beginning research or paper trading, add at least one active AI employee to the selected trading book. Open the guided team setup:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/hedgefund:onboard</span></span></code></pre></div><p>The setup confirms that the trading book exists and has at least one active non-CEO employee.</p><p>The available roles support separation of responsibility:</p><table tabindex="0"><thead><tr><th>Role</th><th>Primary responsibility</th></tr></thead><tbody><tr><td><strong>Chief Investment Officer</strong></td><td>Investment direction and synthesis</td></tr><tr><td><strong>Portfolio Manager</strong></td><td>Book construction and portfolio context</td></tr><tr><td><strong>Trader</strong></td><td>Candidate selection, trade planning, and paper execution</td></tr><tr><td><strong>Risk Manager</strong></td><td>Limits, challenge, escalation, and review</td></tr><tr><td><strong>Operations</strong></td><td>Reconciliation, records, and operating checks</td></tr></tbody></table><p>A personal Trading Office does not need all five roles. The onboarding check requires one active non-CEO employee, so a solo trader can begin with one Trader employee and add research, risk, portfolio, or operations roles when those responsibilities are useful. Administration also supports custom employees and roles.</p><h2 id="_4-choose-the-session-mode" tabindex="-1">4. Choose the session mode <a class="header-anchor" href="#_4-choose-the-session-mode" aria-label="Permalink to &quot;4. Choose the session mode&quot;">​</a></h2><p>When you enter a book, choose how this session should operate:</p><ul><li><strong>Guided</strong> — you initiate or delegate the work; scheduled employee workflows remain deferred.</li><li><strong>Autonomous · Paper trading</strong> — scheduled employee workflows may research, trade, and report on paper without a fresh instruction, subject to their mandates.</li></ul><p>Both modes keep the paper trade pipeline available. Neither mode grants authority to place live broker orders.</p><p>Autonomous · Paper trading applies to scheduled employee workflows. It does not turn approval of a Strategy Lab deployment into an automatic strategy-version execution runtime. The current Strategy Library paper-trade path still creates a reviewable ticket for confirmation.</p><div class="tip custom-block"><p class="custom-block-title">Recommended first setup</p><p>Use Guided mode for <a href="/trading-sandbox-website-preview/wiki/trading-office/quickstart">Your First Strategy</a>. It makes every decision and approval point easy to see before you allow standing workflows to run.</p></div><h2 id="_5-review-mandates-before-autonomy" tabindex="-1">5. Review mandates before autonomy <a class="header-anchor" href="#_5-review-mandates-before-autonomy" aria-label="Permalink to &quot;5. Review mandates before autonomy&quot;">​</a></h2><p>A mandate describes what an employee may do, not only what it has been asked to do. Depending on the role, it can constrain:</p><ul><li>whether the employee may enter a paper trade;</li><li>allowed instruments and symbols;</li><li>maximum notional per trade and open-position limits;</li><li>daily-loss limits and required stops;</li><li>market-session rules;</li><li>escalation behavior and kill-switch state.</li></ul><p>Open the Control Center and choose <strong>Manage mandates</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/hedgefund:control</span></span></code></pre></div><p>Book or account controls can tighten a mandate. They should not be treated as permission to loosen an explicit denial.</p><h2 id="_6-review-scheduled-workflows" tabindex="-1">6. Review scheduled workflows <a class="header-anchor" href="#_6-review-scheduled-workflows" aria-label="Permalink to &quot;6. Review scheduled workflows&quot;">​</a></h2><p>An employee workflow is a standing Office routine with an owner, cadence, symbols or scope, and persisted runs. In Autonomous · Paper trading, due workflows can run without a fresh prompt. In Guided mode, employee mandate ticks stay deferred.</p><p>From the Control Center, choose <strong>Manage workflows</strong> to inspect cadence, symbols, run state, pause, and restart controls. Choose <strong>Inspect activity</strong> to see due, running, waiting, and failed runs.</p><p>Employee workflows are one of several ways Trading Office continues work over time. <a href="/trading-sandbox-website-preview/wiki/trading-office/watches">Automation Tools</a> compares them with watches, backtest jobs, and position monitoring.</p><h2 id="_7-verify-the-office-in-control-center" tabindex="-1">7. Verify the office in Control Center <a class="header-anchor" href="#_7-verify-the-office-in-control-center" aria-label="Permalink to &quot;7. Verify the office in Control Center&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/hedgefund:control</span></span></code></pre></div><p>The Control Center summarizes the active book, session mode, team coverage, mandates, configured workflows, run state, and unread escalations. Its actions let you:</p><ul><li>complete the recommended setup;</li><li>manage the team;</li><li>manage mandates;</li><li>manage workflows;</li><li>inspect recent activity;</li><li>pause all scheduled workflows for the current trading book.</li></ul><p>Use the global pause when the workflow configuration, data, or market context needs review. It invalidates pending and waiting scheduled runs for that book; it is not a substitute for closing open paper positions.</p><h2 id="before-enabling-autonomous-·-paper-trading" tabindex="-1">Before enabling Autonomous · Paper trading <a class="header-anchor" href="#before-enabling-autonomous-·-paper-trading" aria-label="Permalink to &quot;Before enabling Autonomous · Paper trading&quot;">​</a></h2><p>Confirm that you can answer each question:</p><ul><li>Which symbols and instruments may each trading employee use?</li><li>What is the largest acceptable paper notional and risk per trade?</li><li>Is a stop required?</li><li>What daily-loss or position limit should stop new entries?</li><li>How often should each workflow run?</li><li>Which events require escalation instead of action?</li><li>Do you know how to use <code>/hedgefund:control</code> to pause Office workflows and <code>/crons</code> to remove scheduled watches?</li></ul><p>If any answer is unclear, stay in Guided mode and tighten the setup first.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/trading-sandbox-website-preview/wiki/getting-started/tradingview-setup">Connect TradingView</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/quickstart">Your first strategy</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/watches">Automation tools</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/operations">Run your trading office</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/concepts">Concepts and terminology</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/commands">Commands and shortcuts</a></li></ul>',44)])])}const f=t(n,[["render",r]]);export{u as __pageData,f as default};
